import {statsView,profileView,directoryView,awardsView,coachPanel,marketOffersView,chaptersPanel} from './v34-view.js?v=3.5.0';
import {requestRole,PREFERENCES} from './career-plan.js?v=3.5.0';
import {splitWorkerState,joinWorkerState} from './worker-state.js?v=3.5.0';
import {canChange,retireCareer} from './commands.js?v=3.5.0';
import {beginAdvance,setAdvanceMode,settleAdvance,destinationReached} from './simulation.js?v=3.5.0';
import {acknowledgeSport,hasSportPause} from './sport-events.js?v=3.5.0';
import {advanceOptions,advanceHint,sportNotice,playoffLink,playoffsView,masteryPanel,stintPanel} from './v33-view.js?v=3.5.0';
import {EFFECT_TEXT} from './match-effects.js?v=3.5.0';
import {chooseAmbition} from './legacy.js?v=3.5.0';
import {ambitionPanel,stakesPanel,highlightsPanel,reviewPanel,legacyPanel} from './legacy-view.js?v=3.5.0';
