import {defaultBuild,buildCaps,limits,potentialCost,createGame,hero,team,overall,next,upgrade,upgradeCost,badgeLevel,learn,equip,continueMatch,grade,standings,sign,requestTrade,log,activeLeague,competition,playerGames,decide,scouting,syncLeague} from './engine.js?v=3.5.0';
import {save,load,parseSave,listSlots,deleteSlot,hydrateArchive,completeExport} from './storage.js?v=3.5.0';
let focusAdvance=false;
let stopBeforeStart=false,workerPrefix=null,profileId=null,directoryQuery='';
let statsFilter={season:null,phase:'regular',team:'all',sort:'pts',direction:'desc',query:'',page:0},awardFilter={season:null,kind:'mvp'};

let archivePrefix=[],slotMetadata=[],postSeason=null,postConference='Tous',postRound='all';
let s=null,tab='home',sub='attrs',build=defaultBuild(),step=0,busy=false,progress=0,notice='',worker=null,leagueView='Classement',selectedTeam=null,installPrompt=null,creation=false,acting=false,archiveSeason=null,leagueSelection=null;
const $=id=>document.getElementById(id),esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),fmt=n=>Math.round(n).toLocaleString('fr-FR'),btn=(text,action,cls='',disabled=false)=>`<button class="${cls}" data-action="${action}" ${disabled?'disabled':''}>${text}</button>`,meter=(v,max=100)=>`<div class="meter"><i style="width:${Math.min(100,Math.max(0,v/max*100))}%"></i></div>`,pill=t=>`<span class="pill">${esc(t)}</span>`;
function toast(t){$('toast').textContent=t;setTimeout(()=>{$('toast').textContent=''},4000)}
async function persist(){try{await save(s);notice='Sauvegardé sur cet appareil'}catch{notice='Sauvegarde impossible : exportez votre partie';toast(notice)}}
const date=()=>new Date(Date.UTC(REFERENCE.baseYear,8,1+s.day)).toLocaleDateString('fr-FR',{day:'numeric',month:'long',year:'numeric'});
function header(){return `<header><a class="brand" href="#" aria-label="HOOP LEGACY accueil"><span class="logo">H<span>•</span>L</span> HOOP <b>LEGACY</b></a><span class="edition">WORLD TOUR / ${s?'S'+s.season:'2026'}</span>${s?`<span class="save-dot" title="${esc(notice)}">${notice.includes('impossible')?'!':'✓'} <span>${esc(notice||'Sauvegarde locale')}</span></span>`:''}${s?btn('☰','tab:more','small settings-button'):''}</header>`}
function render(){const renderStart=performance.now(),active=document.activeElement,focusId=active?.id,selection=active?.selectionStart,selectionEnd=active?.selectionEnd,focusAction=active?.dataset?.action,opened=[...document.querySelectorAll('details[open]')].map(d=>d.querySelector('summary')?.textContent);if(!s||creation){renderCreation();return}let p=hero(s);$('app').innerHTML=header()+`<div class="shell"><aside><p class="eyebrow">VOTRE CARRIÈRE</p><h2>${esc(p.name)}</h2><p class="muted">${esc(team(s).name)}</p><div class="profile-number">${overall(p)}<small>NOTE GÉNÉRALE</small></div>${nav(false)}<div class="aside-foot">${pill(activeLeague(s).name)}<p>${s.career.stage==='highschool'?'Parcours lycée':s.career.stage==='college'?'Parcours universitaire':'Carrière professionnelle'} · S${s.season}</p><p class="muted">${date()}</p></div></aside><main><div class="page-top"><div><p class="eyebrow">SAISON ${String(s.season).padStart(2,'0')} / ${esc(s.phase).toUpperCase()}</p><h1>${{home:'Le prochain chapitre.',player:'Construisez votre jeu.',career:'Votre trajectoire.',league:'La ligue en mouvement.',life:'Une vie autour du basket.',more:'Réglages & sauvegardes.'}[tab]}</h1></div><span class="date">${date()}</span></div>${profileId?profileView(s,profileId):''}${s.pending&&!s.retired?['home','career'].includes(tab)?pending():`<section class="decision compact-decision"><strong>Une décision vous attend</strong><p>${esc(s.pending.title)}</p>${btn('Voir la décision','tab:home','secondary')}</section>`:''}${sportNotice(s)}${busy?`<section class="panel"><h3>Simulation en cours · ${Math.round(progress*100)} %</h3>${meter(progress,1)}${btn('Arrêter à la prochaine période','stop','secondary')}</section>`:''}${({home:home,player:player,career:career,league:league,life:life,more:more}[tab])()}</main></div>${nav(true)}`;bind();document.querySelectorAll('details').forEach(d=>{if(opened.includes(d.querySelector('summary')?.textContent))d.open=true;});const focus=focusId?$(focusId):focusAction?[...document.querySelectorAll('[data-action]')].find(e=>e.dataset.action===focusAction&&!e.closest('.side-nav')):null;focus?.focus({preventScroll:true});if(focus?.setSelectionRange&&selection!==null&&selection!==undefined)focus.setSelectionRange(selection,selectionEnd);if(focusAdvance&&!acting&&!busy){const target=document.querySelector('[data-action="advance"]:not(:disabled)')||document.querySelector('main h1');if(target){target.tabIndex=-1;target.focus({preventScroll:true});}focusAdvance=false;}performance.measure('hoop-render',{start:renderStart,end:performance.now()});}
function nav(mobile){return `<nav class="${mobile?'bottom-nav':'side-nav'}">${[['home','⌂','Aujourd’hui'],['player','◉','Joueur'],['career','↗','Carrière'],['life','♡','Vie'],['league','▤','Monde']].map(([id,icon,label])=>`<button data-action="tab:${id}" class="${tab===id?'active':''}"><span>${icon}</span>${label}</button>`).join('')}</nav>`}
function pathway(){let stage=s.career.stage;return `<section class="pathway">${[['highschool','01','Lycée'],['college','02','Université'],['pro','03','Carrière pro']].map(([id,n,t])=>`<div class="${stage===id?'current':''}"><span>${n}</span><b>${t}</b><small>${id==='highschool'?s.career.hsYears+' saison(s)':id==='college'?s.career.collegeYears+' saison(s)':s.draftResult?.rank?'Draft n° '+s.draftResult.rank:'NBA & monde'}</small></div>`).join('')}</section>`}
function home(){let p=hero(s),def=activeLeague(s),g=playerGames(s).find(g=>!g.result),st=p.season,scan=s.lastSeasonScouting||scouting(s);return `${pathway()}<section class="hero-panel"><div><div class="eyebrow">${esc(team(s).name)} <span class="orange">/ ${esc(def.name)}</span></div><h2>${esc(p.name)}<span>${esc(p.pos)} · ${p.age} ans · ${esc(s.role)}</span></h2><div class="hero-stats"><div><strong>${overall(p)}</strong><small>GÉNÉRAL</small></div><div><strong>${st.gp?(st.pts/st.gp).toFixed(1):'—'}</strong><small>POINTS / MATCH</small></div><div><strong>+${s.development.gained}</strong><small>ATTRIBUTS DÉVELOPPÉS</small></div></div></div><div class="court" aria-label="Terrain schématique"><div class="court-center"></div><div class="paint"></div><div class="arc"></div><span class="court-player">07</span><span class="court-label">${esc(p.style).toUpperCase()}</span></div></section>${s.match?liveMatch():`<section class="next-event"><div><p class="eyebrow">${s.retired?'CARRIÈRE TERMINÉE':g?esc(leagueDef(g.league).name):'INTERSAISON & ORIENTATION'}</p><h3>${s.retired?'Votre histoire reste ici.':s.pending?'Une décision vous attend':g?esc(team(s,g.home===s.team?g.away:g.home).name):'La saison touche à sa fin'}</h3><p class="muted">${g?.stage==='post'?`${esc(competition(s,g.league).post?.series?.find(p=>p.games.includes(g.id))?.name||'Playoffs')} · Match ${g.gameNumber||'?'} · ${g.neutral?'terrain neutre':g.home===s.team?'à domicile':'à l’extérieur'}`:g?.stage==='playin'?'Play-in · qualification en jeu':`${s.round} / ${def.games} matchs de saison régulière`} · ${s.minutes} minutes prévues</p>${stakesPanel(s,g)}</div><div class="advance"><label class="sr" for="advance-size">Avancer jusqu’à</label><select id="advance-size">${advanceOptions(s)}</select>${btn(s.retired?'Carrière terminée':s.simulation.cursor||hasSportPause(s)?'Reprendre →':'Avancer →','advance','primary',busy||!!s.pending||s.retired)}${advanceHint(s)}</div></section>`}${playoffLink(s)}${highlightsPanel(s)}${s.lastMatch&&!s.match?summary():''}${chaptersPanel(s)}<details class="panel"><summary>Mes objectifs de progression</summary>${ambitionPanel(s)}</details>${reviewPanel(s)}<div class="metrics home-metrics"><article><span>ÉNERGIE</span><strong>${Math.round(100-p.fatigue)}<small>/100</small></strong>${meter(100-p.fatigue)}<p>${p.injury?`Blessure · ${p.injury} jours`:'Disponible'}</p></article><article><span>CONFIANCE DU COACH</span><strong>${Math.round(s.trust)}<small>/100</small></strong>${meter(s.trust)}<p>${s.role} · ${s.minutes} min</p></article><article><span>XP DISPONIBLE</span><strong>${Math.round(Object.values(s.development.xp).reduce((a,b)=>a+b,0))}<small>XP</small></strong><p>6 domaines · allocation ${s.auto?'automatique':'manuelle'}</p></article></div><details class="panel home-journal"><summary>Journal et parcours</summary><div class="two-col"><section class="panel"><div class="section-title"><h3>Journal de carrière</h3><span class="muted">${s.teams.length} clubs et programmes</span></div><div class="timeline">${s.log.slice(0,8).map(e=>`<article><span class="timeline-date">S${e.season} · J${e.day-(e.season-1)*365}</span><div><h4>${esc(e.title)}</h4><p>${esc(e.text)}</p></div></article>`).join('')}</div></section><section class="panel"><p class="eyebrow">${s.career.stage==='highschool'?'OBJECTIF : UNE UNIVERSITÉ':s.career.stage==='college'?'LA NBA EN LIGNE DE MIRE':'VOTRE PROCHAIN PALIER'}</p><h3>${s.career.stage==='highschool'?'Se faire recruter.':s.career.stage==='college'?esc(scan.projection):'Développer votre impact.'}</h3><p class="muted">${s.career.stage==='highschool'?'Vos résultats scolaires, vos performances et votre efficacité déterminent les programmes intéressés.':s.career.stage==='college'?'Après chaque saison universitaire : rester pour progresser ou se déclarer à la draft. Une projection n’est jamais une garantie.':'Les propositions internationales tiennent compte de votre niveau et des besoins de chaque club.'}</p>${s.career.stage!=='pro'?`<p>Études : <b>${Math.round(s.career.academics)}/100</b> · Exposition : <b>${Math.round(s.career.exposure)}/100</b></p>`:''}<div class="focus-stat"><strong>${p.attrs[s.training]}</strong><span>/ ${p.caps[s.training]}<small>${LABELS[s.training]}</small></span></div><p class="muted">XP issue de vos performances et de l’entraînement. Les coûts augmentent aux niveaux élevés, sans plafond de build.</p>${btn('Mon développement ↗','tab:player','secondary')}</section></div></details>`}
function pending(){let e=s.pending;return `<section class="decision"><p class="eyebrow">DÉCISION · LA SIMULATION EST EN PAUSE</p><h2>${esc(e.title)}</h2><p>${esc(e.text)}</p>${e.type==='draft-choice'?`<div class="button-row">${btn('Me déclarer à la draft NBA','decision:draft','primary')}${s.career.collegeYears<4?btn('Rester une saison à l’université','decision:stay','secondary'):''}</div>`:e.type==='contract'?`${marketOffersView(s)}${e.canDecline?btn('Rester dans mon club','decision:decline','secondary'):''}`:`<div class="offers">${(e.choices||[]).map(([id,title,detail])=>`<article><h3>${esc(title)}</h3>${detail?`<p class="muted">${esc(detail)}</p>`:''}${btn('Choisir','decision:'+id,'primary')}</article>`).join('')}</div>`}</section>`}

function liveMatch(){let m=s.match,events=s.mode==='key'?m.events.filter(e=>e.key).slice(-5):m.events.slice(-8);return `<section class="panel live"><p class="eyebrow">MATCH AUTOMATIQUE · ${s.mode==='key'?'MOMENTS CLÉS':'SUIVI DÉTAILLÉ'}${m.ot?' · PROLONGATION '+m.ot:''}</p><div class="scoreboard"><span>${esc(team(s,m.home).name)}</span><strong>${m.score[0]} <em>:</em> ${m.score[1]}</strong><span>${esc(team(s,m.away).name)}</span></div><p class="muted">${m.n} / ${m.total} possessions · les attributs, tendances et rotations déterminent le match.</p>${meter(m.n,m.total)}<div class="match-events">${events.map(e=>`<p><b>${e.score.join('–')}</b> ${esc(e.text)}</p>`).join('')||'<p>Le match commence. Les joueurs décident automatiquement.</p>'}</div><div class="button-row">${btn(s.mode==='key'?'Voir les prochains moments':'Voir la suite','watch','primary')}${btn('Afficher le résultat final','finish','secondary')}</div><p class="muted">Changer de présentation ne change ni les actions, ni le résultat.</p></section>`}

function summary(){let m=s.lastMatch,b=m.box[s.hero];return `<section class="panel"><div class="section-title"><h3>Dernier match</h3>${pill(b?.min?'Note '+grade(m.grade):'Non entré en jeu')}</div><div class="scoreboard final-score"><span>${esc(team(s,m.home).name)}</span><strong>${m.score[0]} <em>:</em> ${m.score[1]}</strong><span>${esc(team(s,m.away).name)}</span></div><div class="stat-strip">${[['Points',b.pts],['Rebonds',b.reb],['Passes',b.ast],['Minutes',b.min.toFixed(1)],['Tirs',b.fgm+'/'+b.fga],['3 points',b.tpm+'/'+b.tpa]].map(([l,v])=>`<div><strong>${v}</strong><span>${l}</span></div>`).join('')}</div><details><summary>Pourquoi cette note ? · Feuille de match</summary><p>${b?.min?`Base 43 + production ${Number(m.reasons['Production et efficacité']||0).toFixed(1)} ; note limitée de 20 à 99. Temps joué : ${b.min.toFixed(1)} minutes.`:'Aucune note sportive : vous n’êtes pas entré en jeu.'}</p>${boxTable(m.box)}</details></section>`}
function boxTable(box){return `<div class="table-scroll"><table><thead><tr><th>Joueur</th><th>MIN</th><th>PTS</th><th>REB</th><th>PD</th><th>Tirs</th><th>3 PTS</th><th>LF</th><th>INT</th><th>CTR</th><th>BP</th></tr></thead><tbody>${Object.values(box).map(b=>`<tr class="${b.id===s.hero?'you':''}"><td>${esc(b.name||s.players.find(p=>p.id===b.id)?.name)}</td><td>${b.min.toFixed(1)}</td><td>${b.pts}</td><td>${b.reb}</td><td>${b.ast}</td><td>${b.fgm}/${b.fga}</td><td>${b.tpm}/${b.tpa}</td><td>${b.ftm}/${b.fta}</td><td>${b.stl}</td><td>${b.blk}</td><td>${b.tov}</td></tr>`).join('')}</tbody></table></div>`}
function developmentReport(){let p=hero(s),d=s.development,year=d.year,previous=d.lastSeason;const changes=(start,end)=>Object.entries(GROUPS).map(([name,keys])=>{let delta=keys.reduce((n,k)=>n+(end[k]-start[k]),0)/keys.length;return `<span>${name} <b>${delta>=0?'+':''}${delta.toFixed(1)}</b></span>`}).join('');return `<section class="panel development-report"><h3>Votre évolution</h3><p class="muted">Depuis ${year?.season===s.season?'le début du suivi de cette saison':'la dernière mise à jour'} : ${fmt(year?.sources.match||0)} XP en match · ${fmt(year?.sources.training||0)} XP à l’entraînement.</p>${year?`<div class="development-changes">${changes(year.start,p.attrs)}</div>`:''}<p class="muted">Variation moyenne par attribut dans chaque domaine, après progression, âge et récupération.</p>${previous?`<details><summary>Bilan de la saison ${previous.season}</summary><div class="development-changes">${changes(previous.start,previous.end)}</div><p>${previous.gains} points améliorés · ${fmt(previous.sources.match)} XP en match · ${fmt(previous.sources.training)} XP à l’entraînement.</p>${Object.keys(previous.aging).length?`<p>Évolution liée à l’âge : ${Object.entries(previous.aging).map(([k,v])=>`${LABELS[k]} ${v>0?'+':''}${v}`).join(' · ')}.</p>`:''}</details>`:''}${p.age>=30?'<p>Conserver votre explosivité demande davantage d’XP avec l’âge. Le tir, les passes et le jeu au poste restent plus faciles à entretenir. Vous pouvez réorienter votre programme dans Carrière.</p>':''}</section>`}
function player(){let p=hero(s);return `<div class="tabs">${[['attrs','Attributs'],['badges','Badges'],['tech','Techniques'],['health','Profil & santé']].map(([id,t])=>btn(t,'sub:'+id,sub===id?'selected':'')).join('')}</div>${sub==='attrs'?`${developmentReport()}<p class="muted">Attributs de 25 à 99, sans plafond individuel. L’XP reste dans le domaine où elle est gagnée.</p><label class="check"><input id="auto" type="checkbox" ${s.auto?'checked':''}> Allouer automatiquement l’XP</label><div class="attribute-grid">${Object.entries(GROUPS).map(([g,ks])=>`<section class="panel"><div class="section-title"><h3>${g}</h3>${pill(Math.floor(s.development.xp[g])+' XP disponibles')}</div>${ks.map(k=>{let c=upgradeCost(p,k);return `<div class="attribute"><div><label>${LABELS[k]}</label><span><b>${Math.round(p.attrs[k])}</b> / 99</span>${meter(p.attrs[k],99)}</div>${btn('+1','upgrade:'+k,'small',p.attrs[k]>=99||s.development.xp[g]<c||!!s.match)}<small>${p.attrs[k]>=99?'Maximum commun atteint':`${fmt(c)} XP pour le prochain point${costDetails(p,k).ageFactor>=1.1?' · effort lié à l’âge ×'+costDetails(p,k).ageFactor.toFixed(1):''}`}</small></div>`}).join('')}</section>`).join('')}</div>${s.development.performance?`<section class="panel"><h3>XP du dernier match</h3><p>Efficacité ×${s.development.performance.efficiency} · ligue ×${s.development.performance.coefficient} · charge de matchs de la semaine ×${s.development.performance.normalizer}</p><p>${Object.entries(s.development.performance.amounts).map(([d,v])=>`${d} : +${v}`).join(' · ')}</p></section>`:''}`:sub==='badges'?`<p class="muted">Les badges progressent avec leur utilisation en match. Leur effet est limité à l’action décrite et reste plafonné pour conserver le poids des attributs et de l’adversaire.</p><div class="catalog">${BADGES.map(b=>{let lv=badgeLevel(p,b),xp=p.badges[b.id]||0;return `<article class="panel"><span class="badge-icon ${lv?'unlocked':''}">◇</span><h3>${b.name}</h3>${pill(LEVELS[lv])}<p>${b.description}</p><p class="muted">${EFFECT_TEXT[b.context]}</p><p class="muted">${lv?`Usage : ${xp} · Prochain palier à ${(Math.floor(xp/80)+1)*80} usages, sous réserve du niveau d’attribut.`:`Nécessite ${LABELS[b.attr]} ≥ ${b.threshold} (actuel ${p.attrs[b.attr]}).`}</p>${meter(xp%80,80)}</article>`}).join('')}</div>`:sub==='tech'?`<p class="muted">Apprenez puis équipez jusqu’à trois techniques. Le bonus ne s’applique qu’aux actions correspondantes. Désactivez l’allocation automatique d’XP pour en réserver à l’apprentissage.</p><div class="catalog">${TECHNIQUES.map(t=>`<article class="panel"><p class="eyebrow">${LABELS[t.attr]} ≥ ${t.threshold}</p><h3>${t.name}</h3><p>${EFFECT_TEXT[t.context]}</p><p class="muted">Active lorsqu’elle est équipée. Seule la meilleure technique du même contexte s’applique.</p><p class="muted">${p.attrs[t.attr]<t.threshold?'Verrouillée : attribut insuffisant.':`Apprentissage : ${t.cost*25} XP du domaine ${domainOf(t.attr)}.`}</p>${p.learned.includes(t.id)?btn(p.equipped.includes(t.id)?'Équipée ✓':'Équiper','equip:'+t.id,'secondary'):btn('Apprendre','learn:'+t.id,'secondary',p.attrs[t.attr]<t.threshold||s.development.xp[domainOf(t.attr)]<t.cost*25)}</article>`).join('')}</div>`:`<section class="panel"><h2>${esc(p.name)}</h2><p>${p.age} ans · ${esc(p.nation)} · ${p.height} cm · ${p.weight} kg · Envergure ${p.wingspan} cm</p><p>Poste principal ${p.pos} · secondaire ${p.secondary} · ${p.style}</p><p class="muted">${esc(s.roleReason||'Le coach ajuste le rôle selon vos performances et la concurrence.')}</p>${btn('Demander un rôle plus important','role-request','secondary',!!s.pending||!!s.match)}<label>Tendances<select id="tendency-mode"><option value="auto" ${p.tendencyMode!=='manual'?'selected':''}>Automatiques selon mes compétences</option><option value="manual" ${p.tendencyMode==='manual'?'selected':''}>Personnalisées</option></select></label>${p.tendencyMode==='manual'?Object.entries(tendencies(p)).filter(([k])=>k!=='pass').map(([k,v])=>`<label>${{three:'Tir à trois points',drive:'Pénétration',post:'Jeu au poste',mid:'Mi-distance'}[k]}<input type="range" id="tendency-${k}" min="5" max="100" value="${v}"></label>`).join(''):''}<div class="metrics">${[['Fatigue',p.fatigue],['Lecture du jeu',s.iq],['Maîtrise du système',s.system],['Tendance récente',s.form]].map(([l,v])=>`<article><span>${l}</span><strong>${Math.round(v)}</strong>${meter(v)}</article>`).join('')}</div><p>${p.injury?`Rééducation : encore ${p.injury} jours. Aucun match joué pendant l’indisponibilité.`:'Disponible. La récupération et la fatigue influencent vos performances.'}</p><p class="muted">La vidéo améliore la lecture du jeu : moins de pertes de balle et de meilleurs choix de tir. La tendance récente décrit vos dernières notes ; elle n’ajoute aucun bonus. La fatigue augmente avec les minutes et diminue avec le repos.</p><p class="muted">La taille intervient dans les duels et les rebonds. L’agilité agit sur les changements d’appui, la détente sur les finitions aériennes, contres et rebonds, et l’envergure sur la contestation et les rebonds. Ces effets restent modestes. Le poids est descriptif. Les défenses peuvent aider face à une menace majeure, libérant des espaces pour ses coéquipiers.</p></section>${masteryPanel(s)}`}`}
function career(){let p=hero(s),stage=s.career.stage;return `${pathway()}${chaptersPanel(s)}${coachPanel(s)}${clubProjectView(s)}${ambitionPanel(s,true)}${reviewPanel(s,true)}${legacyPanel(s)}${stintPanel(s)}<details class="panel"><summary>Entraînement, rôle et contrat</summary><div class="two-col"><section class="panel"><p class="eyebrow">ENTRAÎNEMENT ASSISTÉ</p><h3>Votre programme</h3><label>Domaine prioritaire<select id="training-domain">${DOMAINS.map(d=>`<option ${s.trainingPlan.domain===d?'selected':''}>${d}</option>`).join('')}</select></label><label>Accompagnement<select id="training-mode"><option value="assisted" ${s.trainingPlan.mode==='assisted'?'selected':''}>Assisté · ajuste l’effort à la fatigue</option><option value="manual" ${s.trainingPlan.mode==='manual'?'selected':''}>Manuel · respecter mon intensité</option></select></label><label>Intensité<select id="training-intensity">${[['light','Légère'],['normal','Normale'],['hard','Soutenue']].map(([v,l])=>`<option value="${v}" ${s.trainingPlan.intensity===v?'selected':''}>${l}</option>`).join('')}</select></label><label>Activité prioritaire<select id="activity">${[['individuel','Travail individuel'],['video','Vidéo et lecture du jeu'],['repos','Récupération'],['famille','Temps pour les proches'],...(stage!=='pro'?[['etudes','Études']]:[])].map(([v,l])=>`<option value="${v}" ${s.activity===v?'selected':''}>${l}</option>`).join('')}</select></label><label>Compétence à privilégier<select id="training">${KEYS.map(k=>`<option value="${k}" ${s.training===k?'selected':''}>${LABELS[k]}</option>`).join('')}</select></label><p class="muted">Les séances suivent le calendrier, sans clic répétitif. L’entraînement et les performances alimentent les mêmes six domaines.</p><p>XP gagnée : <b>${fmt(s.development.sources.match)} en match</b> · <b>${fmt(s.development.sources.training)} à l’entraînement</b>.</p></section><section class="panel"><p class="eyebrow">${stage==='pro'?'CONTRAT & MOBILITÉ':'RECRUTEMENT & DRAFT'}</p><h3>${esc(team(s).name)}</h3>${stage==='pro'?`<h2>${fmt(p.contract.salary)} <small>€ / saison</small></h2><p>${p.contract.years} saison(s) restante(s) · option ${esc(p.contract.option)}</p>${btn('Demander à mon agent d’explorer le marché','trade','primary',!!s.match||!!s.pending||s.retired)}<p class="muted">Votre club peut refuser une demande. Les offres tiennent compte de votre niveau, du rôle et des besoins au poste.</p>`:`<p>Études : <b>${Math.round(s.career.academics)}/100</b> · exposition : <b>${Math.round(s.career.exposure)}/100</b></p><h3>${esc((s.lastSeasonScouting||scouting(s)).projection)}</h3><p class="muted">Lycée jusqu’à 18 ans, puis choix d’université. Après au moins une saison universitaire, vous choisissez quand tenter la draft. Les joueurs non draftés reçoivent des possibilités à l’étranger.</p>`}<hr><h3>${esc(s.role)} · ${s.minutes} minutes prévues</h3><p>${esc(s.roleReason||'Vos performances et la concurrence au poste déterminent votre rôle.')}</p>${btn('Demander davantage de responsabilités','role-request','secondary',!!s.pending||!!s.match)}<p class="muted">Le coach garde la décision finale.</p></section></div></details><section class="panel"><h3>Votre histoire</h3><details><summary>Palmarès · ${s.trophies.length} distinction(s)</summary><p>${s.trophies.map(esc).join(' · ')||'Les premiers trophées restent à gagner.'}</p></details><details><summary>Mes saisons · ${s.history.length}</summary>${s.history.map(h=>`<div class="fixture"><b>S${h.season}</b><span>${esc(h.team)} · ${esc(leagueDef(h.league)?.name||h.league)}<br>${h.stats.gp} matchs · ${h.stats.gp?(h.stats.pts/h.stats.gp).toFixed(1):0} points / match</span><b>${h.ovr} GÉN</b></div>`).join('')}</details><details><summary>Journal intégral · ${s.journal.length} événements</summary><label>Rechercher dans ma carrière<input id="journal-query" type="search" placeholder="Draft, blessure, champion…"></label><div id="journal-results">${journalRows(s.journal.slice(-35).reverse())}</div></details></section>${s.retired?`<section class="decision"><h2>Votre héritage</h2><p>${s.history.length} saisons · ${s.trophies.length} distinctions · ${fmt(netWorth(s))} € de patrimoine.</p><p>${s.life.children.length} enfant(s), ${s.life.partner?'une vie de couple':'une trajectoire personnelle libre'}. Les archives de votre carrière restent consultables.</p></section>`:''}`}
function journalRows(events){return events.map(e=>`<p><b>S${e.season} · ${esc(e.title)}</b><br>${esc(e.text)}</p>`).join('')||'<p>Aucun événement.</p>'}
function life(){return lifeView(s)}
function league(){let lid=leagueSelection||s.league,def=leagueDef(lid),c=competition(s,lid),rank=standings(s,lid),club=selectedTeam&&def.teams.includes(team(s,selectedTeam)?.name)?team(s,selectedTeam):rank[0],archive=s.archives.find(a=>a.season===Number(archiveSeason)),ac=archive?.competitions?.find(c=>c.id===lid);let games=ac?ac.games:c.schedule;return `<section class="league-heading"><label>Championnat<select id="league-select">${LEAGUES.map(l=>`<option value="${l.id}" ${lid===l.id?'selected':''}>${esc(l.name)} · ${l.games} matchs</option>`).join('')}</select></label><div><h2>${esc(def.name)}</h2><p>${def.teams.length} équipes · ${def.games} matchs réguliers · ${def.minutes} minutes</p>${pill(def.country)} ${pill(c.phase)}</div></section><p class="muted">NBA : identités réelles au départ, nouvelles générations fictives · Référence ${REFERENCE.season}. ${def.note||'Calendrier, évaluations et contrats simulés. Autres ligues : joueurs fictifs.'}</p><div class="tabs">${['Classement','Playoffs','Calendrier','Équipes','Statistiques','Distinctions','Dossiers','Draft & marché'].map(v=>btn(v,'league:'+v,v===leagueView?'selected':'')).join('')}</div><section class="panel">${leagueView==='Playoffs'?playoffsView(s,lid,{season:postSeason,conference:postConference,round:postRound}):leagueView==='Classement'?`<div class="table-scroll"><table><thead><tr><th>#</th><th>Équipe</th><th>V</th><th>D</th><th>Diff.</th>${lid==='nba'?'<th>Conférence</th>':''}</tr></thead><tbody>${rank.map((t,i)=>`<tr class="${t.id===s.team?'you':''}"><td>${i+1}</td><td>${btn(esc(t.name)+(t.id===s.team?' · VOUS':''),'team:'+t.id,'link')}</td><td>${t.wins}</td><td>${t.losses}</td><td>${t.for-t.against}</td>${lid==='nba'?`<td>${t.conference}</td>`:''}</tr>`).join('')}</tbody></table></div><p class="muted">Classement de saison régulière uniquement. ${def.playIn?'Play-in puis ':''}${def.playoff} équipes en phases finales. ${lid==='nba'?'Huit qualifiés par conférence, séries au meilleur des sept matchs.':lid==='euroleague'?'Quarts au meilleur des cinq matchs, puis Final Four.':''}</p>${c.champion?`<h3>Champion : ${esc(team(s,c.champion).name)}</h3>`:''}`:leagueView==='Calendrier'?`<label>Saison<select id="calendar-season"><option value="">Saison actuelle</option>${s.archives.map(a=>`<option value="${a.season}" ${a.season===Number(archiveSeason)?'selected':''}>Saison ${a.season}</option>`).join('')}</select></label><label>Équipe<select id="calendar-team">${rank.map(t=>`<option value="${t.id}" ${t.id===(selectedTeam|| (rank.some(t=>t.id===s.team)?s.team:club.id))?'selected':''}>${esc(t.name)}</option>`).join('')}</select></label>${games.filter(g=>g.home===(selectedTeam||(rank.some(t=>t.id===s.team)?s.team:club.id))||g.away===(selectedTeam||(rank.some(t=>t.id===s.team)?s.team:club.id))).sort((a,b)=>a.day-b.day).map(g=>`<div class="fixture"><span>J${g.day-((archive?.season||s.season)-1)*365}<br>${g.stage==='regular'?'Saison':g.stage==='playin'?'Play-in':'Playoffs'}</span><span>${esc(team(s,g.home).name)}<br>${esc(team(s,g.away).name)}</span><b>${g.score?g.score.join(' – '):g.result?g.result.score.join(' – '):'À venir'}</b></div>`).join('')}`:leagueView==='Équipes'?`<label>Équipe<select id="team-select">${rank.map(t=>`<option value="${t.id}" ${t.id===club.id?'selected':''}>${esc(t.name)}</option>`).join('')}</select></label><h3>${esc(club.name)}</h3><p>Compétitions : ${club.competitions.map(id=>leagueDef(id).name).join(' + ')}</p><p class="muted">Un seul effectif partagé entre championnat national et EuroLeague.</p><div class="table-scroll"><table><thead><tr><th>Joueur</th><th>Poste</th><th>Âge</th><th>Général</th><th>Contrat</th></tr></thead><tbody>${club.roster.map(id=>{let p=s.players.find(q=>q.id===id);return `<tr class="${id===s.hero?'you':''}"><td>${btn(esc(p.name),'profile:'+p.id,'link')} ${p.injury?'✚':''}</td><td>${p.pos}</td><td>${p.age}${p.ageEstimated?' ≈':''}</td><td>${overall(p)}</td><td>${p.contract.years} ans</td></tr>`}).join('')}</tbody></table></div>`:leagueView==='Statistiques'?statsView(s,lid,statsFilter):leagueView==='Distinctions'?awardsView(s,lid,awardFilter):leagueView==='Dossiers'?directoryView(s,directoryQuery):`<h3>Draft NBA & mobilité internationale</h3><p>${s.draftResult?s.draftResult.rank?'Vous avez été sélectionné en position '+s.draftResult.rank+'.':'Vous n’avez pas été drafté. La progression à l’étranger peut ouvrir la NBA.':'La draft se prépare au lycée puis à l’université. Votre rang dépend du niveau, de l’efficacité, des performances et de la promotion concurrente.'}</p><p class="muted">Les transferts conservent le même joueur. Le club quitté recrute un remplaçant ; le club d’arrivée ajuste son effectif. Les matchs déjà joués restent inchangés.</p>${(s.lastDraft||[]).slice(0,20).map(p=>`<div class="fixture"><span>${esc(p.name)} · ${p.pos}</span><span>${esc(p.team)}</span><b>${p.ovr}</b></div>`).join('')}${s.log.filter(e=>['Contrat signé','Draft NBA','Transfert refusé'].includes(e.title)).slice(0,8).map(e=>`<p><b>${esc(e.title)}</b><br>${esc(e.text)}</p>`).join('')}`}</section>`}
function slotLabel(m){return m?`${m.name} · ${m.club} · S${m.season}${m.retired?' · Retraite':''}${m.savedAt?' · '+new Date(m.savedAt).toLocaleString('fr-FR'):''}`:'Vide'}
function saveSlots(){return [1,2,3].map(i=>{const m=slotMetadata.find(m=>m.key==='slot'+i);return `<article class="save-slot"><h4>Emplacement ${i}</h4><p>${esc(slotLabel(m))}</p><div class="button-row">${btn(m?'Remplacer':'Sauver','save:'+i,'small')}${btn('Charger','load:'+i,'small',!m)}${btn('Supprimer','delete:'+i,'small',!m)}</div></article>`}).join('')}
function more(){return `<p class="eyebrow">HOOP LEGACY · VERSION ${VERSION}</p><div class="two-col"><section class="panel"><h3>Sauvegardes</h3><p class="muted">Sauvegarde automatique après chaque action, sur cet appareil. Exportez une copie pour changer de téléphone.</p><div class="button-row">${btn('Exporter en JSON','export','primary')}<label class="button secondary">Importer un JSON<input class="sr" type="file" id="import" accept=".json,application/json"></label></div>${saveSlots()}${slotMetadata.some(m=>m.key.startsWith('before-new-'))?`<details><summary>Autres carrières conservées</summary>${slotMetadata.filter(m=>m.key.startsWith('before-new-')).map(m=>`<p>${esc(slotLabel(m))} ${btn('Charger','load:'+m.key,'small')}</p>`).join('')}</details>`:''}<p class="muted">Une sauvegarde valide reste intacte si l’import échoue.</p>${btn('Restaurer le dernier autosave de secours','load:rollback','secondary')}</section><section class="panel"><h3>Réglages de match</h3><label>Présentation<select id="mode">${[['quick','Simulation rapide'],['key','Moments clés'],['detail','Suivi détaillé']].map(([k,l])=>`<option value="${k}" ${s.mode===k?'selected':''}>${l}</option>`).join('')}</select></label><p class="muted">Un seul moteur pour les trois modes. Les longues avances sont simulées rapidement ; les matchs individuels suivent votre mode préféré.</p><h3>Installer sur téléphone</h3>${installPrompt?btn('Installer HOOP LEGACY','install','secondary'):'<p class="muted">iPhone : dans Safari, Partager → Sur l’écran d’accueil. Android : menu du navigateur → Installer l’application, si proposé. Chargez une première fois avant de jouer hors ligne.</p>'}${btn('Créer une autre carrière','new','secondary')} ${btn('Prendre ma retraite','retire','secondary',s.retired||!!s.match||!!s.pending)}</section></div><section class="panel"><h3>Palmarès & saisons</h3>${s.legacyArchive?`<p class="muted">Ancienne carrière conservée : ${esc(s.legacyArchive.team)} · ${s.legacyArchive.stats.gp} matchs.</p>${btn('Exporter l’archive de mon ancienne saison','export-legacy','secondary')}`:''}<div class="stat-strip">${[['Points',s.records?.pts||0],['Rebonds',s.records?.reb||0],['Passes',s.records?.ast||0]].map(([l,n])=>`<div><strong>${n}</strong><span>Record · ${l}</span></div>`).join('')}</div><p>${s.trophies.map(esc).join(' · ')||'Votre palmarès reste à écrire.'}</p><details><summary>Mes saisons · ${s.history.length}</summary>${s.history.map(h=>`<div class="fixture"><b>Saison ${h.season}</b><span>${esc(h.team)}<br>${h.stats.gp} matchs · ${h.stats.gp?(h.stats.pts/h.stats.gp).toFixed(1):0} points / match</span><span>Champion : ${esc(h.champion)}<br>MVP : ${esc(h.mvp)}</span></div>`).join('')||'<p class="muted">Votre première saison apparaîtra ici après les récompenses.</p>'}</section><section class="panel"><details><summary>Aide, règles & limites de cette version</summary><p>MJ : meneur (dans un profil) ou matchs joués (statistiques). AR : arrière. AI : ailier. AF : ailier fort. P : pivot. PTS : points. REB : rebonds. PD : passes décisives. LF : lancers francs. INT : interceptions. CTR : contres. BP : balles perdues. MIN : minutes.</p><p>Les notes vont de 25 à 99, sans correspondre à un pourcentage de réussite. La note générale est pondérée par poste ; la fatigue, le contexte défensif et les tendances interviennent séparément.</p><p>Formats de référence 2025–26 : NBA 82, EuroLeague 38, France 30, Espagne 34, Allemagne 34, Italie 30, NBL 33. Effectifs NBA du 21 octobre 2025 pour les nouvelles parties, autres joueurs fictifs. Notes, salaires et certains âges sont estimés pour le jeu. NCAA : sélection de 32 programmes, 31 matchs simulés ; lycée : circuit fictif de 24 matchs. Les calendriers scolaires réels varient. Les règles financières et les transferts restent simplifiés ; les promotions/relégations nationales et les coupes ne sont pas simulées.</p><p>Les attributs, badges et techniques modifient les probabilités contextuelles. Le tir dépend de la compétence, de la contestation et de la fatigue. Les matchs sont entièrement automatiques. Aucun Takeover ni bonus de commande manuelle.</p><p>Version ${VERSION} · Pack mondial 2025–26 · Sauvegarde schéma 4.</p></details></section>`}
const steps=['Identité','Départ','Parcours','Mensurations','Poste','Style','Validation'];
function field(label,id,value,type='text',extra=''){return `<label>${label}<input id="${id}" type="${type}" value="${esc(value)}" ${extra}></label>`}
function renderCreation(){let l=limits(build);let content=[`${field('Nom du joueur','b-name',build.name,'text','maxlength="35"')}<label>Mode de création<select id="b-mode"><option value="custom">Personnalisé</option><option value="random">Aléatoire</option><option value="hybrid">Hybride : physique aléatoire, style libre</option></select></label>`,`${field('Âge','b-age',build.age,'number','min="16" max="25"')}<label>Point de départ<select id="b-path">${[['young','Lycée · 16–17 ans → recrutement universitaire'],['prospect','Université · une à quatre saisons avant la draft'],['rookie','Rookie NBA · commencer directement en pro']].map(([v,t])=>`<option value="${v}" ${build.path===v?'selected':''}>${t}</option>`).join('')}</select></label>`,`${field('Nationalité / origine','b-nation',build.nation,'text','maxlength="60"')}<p class="muted">Votre origine fait partie de votre identité. Elle ne donne aucun bonus sportif automatique.</p>`,`${field('Taille (cm)','b-height',build.height,'number','min="175" max="225"')}${field('Poids (kg)','b-weight',build.weight,'number','min="65" max="140"')}${field('Envergure (cm)','b-wingspan',build.wingspan,'number','min="175" max="240"')}`,`<label>Poste principal<select id="b-pos">${['MJ','AR','AI','AF','P'].map(v=>`<option ${build.pos===v?'selected':''}>${v}</option>`).join('')}</select></label><label>Poste secondaire<select id="b-secondary">${['MJ','AR','AI','AF','P'].map(v=>`<option ${build.secondary===v?'selected':''}>${v}</option>`).join('')}</select></label><p class="muted">MJ : meneur · AR : arrière · AI : ailier · AF : ailier fort · P : pivot.</p>`,`<div class="style-options">${Object.keys(STYLES).map(v=>btn(v,'style:'+v,build.style===v?'selected':'secondary')).join('')}</div><p class="muted">Ce choix oriente vos compétences de départ, sans verrouiller votre carrière.</p>`,`<p class="eyebrow">${esc(build.style).toUpperCase()} / ${build.pos}</p><h2>${esc(build.name)}</h2><p>${build.age} ans · ${esc(build.nation)}<br>${build.height} cm · ${build.weight} kg · Envergure ${build.wingspan} cm</p><p>Points forts : ${STYLES[build.style].map(k=>LABELS[k]).join(', ')||'profil équilibré'}</p><p>À développer : ${KEYS.filter(k=>!STYLES[build.style].includes(k)).slice(0,4).map(k=>LABELS[k]).join(', ')}</p><p>${build.path==='young'?'Lycée : des saisons complètes, puis choix d’université.':build.path==='prospect'?'Université : progressez, puis choisissez quand tenter la draft.':'NBA : 82 matchs de saison régulière et concurrence professionnelle.'}</p><p class="muted">${BADGES.filter(b=>build.caps[b.attr]>=b.threshold).length} badges et ${TECHNIQUES.filter(t=>build.caps[t.attr]>=t.threshold).length} techniques accessibles à terme. Chaque attribut pourra progresser jusqu’à 99 avec de l’XP, sans plafond individuel.</p>`][step];$('app').innerHTML=header()+`<main class="creation"><div class="creation-heading"><p class="eyebrow">NOUVELLE CARRIÈRE / ${String(step+1).padStart(2,'0')} — 07</p><h1>Chaque légende<br>commence quelque part<span class="orange">.</span></h1><p class="muted">Créez le joueur. Écrivez la suite sur le terrain.</p></div><section class="creator panel"><div class="step-track">${steps.map((t,i)=>`<span class="${i<=step?'on':''}" title="${t}"></span>`).join('')}</div><p class="eyebrow">ÉTAPE ${step+1}</p><h2>${steps[step]}</h2>${content}<div class="creator-footer">${btn('← Retour','prev','secondary',step===0)}${btn(step===6?'Entrer dans la ligue →':'Continuer →',step===6?'create':'next-step','primary')}</div>${s?btn('Revenir à ma carrière','cancel-new','link'):''}<hr><label class="button secondary">Importer une carrière<input class="sr" type="file" id="import" accept=".json,application/json"></label></section><p class="creation-note">Ligues réelles · Effectifs NBA de référence · Sauvegarde sur votre appareil</p></main>`;bind()}
function readBuild(){for(let k of ['name','age','nation','path','height','weight','wingspan','pos','secondary']){let el=$('b-'+k);if(el)build[k]=['age','height','weight','wingspan'].includes(k)?Number(el.value):el.value.trim()}if(!build.name)build.name='Joueur';build.age=Math.min(25,Math.max(16,build.age||19));build.height=Math.min(225,Math.max(175,build.height||195));build.weight=Math.min(140,Math.max(65,build.weight||88));build.wingspan=Math.min(240,Math.max(175,build.wingspan||202));if(step===1)build.age=build.path==='young'?Math.min(17,Math.max(16,build.age)):build.path==='prospect'?Math.min(21,Math.max(18,build.age)):Math.max(19,build.age);if(step===3)build.caps=buildCaps(build);if(step===0&&$('b-mode')?.value!=='custom'){let a=new Uint32Array(4);crypto.getRandomValues(a);build.seed=a[0]||1;build.height=180+a[1]%36;build.weight=75+a[2]%41;build.wingspan=build.height+5+a[3]%12;if($('b-mode').value==='random'){build.style=Object.keys(STYLES)[a[0]%5];build.pos=['MJ','AR','AI','AF','P'][a[1]%5]}build.caps=buildCaps(build)}}
async function action(a){if(busy&&!['stop'].includes(a)&&!a.startsWith('tab:'))return;let [act,arg]=a.split(':');if(act==='profile'){profileId=arg;render();document.querySelector('.player-dossier')?.focus();return;}if(act==='close-profile'){profileId=null;render();return;}if(act==='stats-prev'||act==='stats-next'){statsFilter.page=Math.max(0,statsFilter.page+(act==='stats-next'?1:-1));render();return;}if(act==='tab'){tab=arg;if(tab==='more')slotMetadata=await listSlots();render();return}if(act==='playoffs'){tab='league';leagueView='Playoffs';leagueSelection=s.league;render();return}if(act==='sub'){sub=arg;render();return}if(act==='league'){leagueView=arg;render();return}if(act==='team'){selectedTeam=arg;leagueView='Équipes';render();return}if(act==='prev'){readBuild();step--;render();return}if(act==='next-step'){readBuild();if(step===6&&potentialCost(build.caps)>CFG.budget){toast('Réduisez le potentiel pour respecter le budget.');return}step++;render();return}if(act==='style'){build.style=arg;build.caps=buildCaps(build);render();return}if(act==='create'){s=createGame(build);creation=false;step=0;await persist();render();return}if(act==='cancel-new'){creation=false;render();return}if(act==='new'){if(confirm('Créer un autre joueur ? Votre carrière actuelle sera conservée dans un emplacement libre ou une copie de secours.')){slotMetadata=await listSlots();let free=[1,2,3].find(i=>!slotMetadata.some(m=>m.key==='slot'+i));await save(s,free?'slot'+free:'before-new-'+Date.now());build=defaultBuild();step=0;creation=true;render()}return}
if(['upgrade','learn','equip','trade','role-request','retire','life','relation'].includes(act)&&!canChange(s,{busy}))return;
if(['watch','finish'].includes(act)&&!canChange(s,{busy,match:true}))return;
if(act==='advance'){
 if(!canChange(s,{busy}))return;
 acknowledgeSport(s);
 setAdvanceMode(s,$('advance-size')?.value||s.simulation.mode);
 const cursor=beginAdvance(s),val=s.simulation.mode;
 if(val==='1'){
  busy=true;next(s);settleAdvance(s,true);busy=false;
 }else if(val==='match'&&s.mode!=='quick'){
  busy=true;
  for(let n=0;n<500&&!s.match&&!s.pending&&!s.retired&&!hasSportPause(s)&&!destinationReached(s);n++)next(s);
  settleAdvance(s);busy=false;
 }else{
  busy=true;progress=0;stopBeforeStart=false;render();await persist();if(stopBeforeStart){busy=false;render();return;}const payload=splitWorkerState(s);workerPrefix=payload.prefix;
  worker=new Worker('./worker.js?v=3.5.0',{type:'module'});
  let updates=Promise.resolve();
  const activeWorker=worker;
  worker.onmessage=e=>{
   updates=updates.then(async()=>{
    const data=e.data,finished=data.type!=='progress';
    if(data.state)s=joinWorkerState(data.state,workerPrefix);
    if(!finished)progress=data.value;
    else{activeWorker.terminate();worker=null;settleAdvance(s);if(data.type==='error')toast(data.message);}
    await persist();if(finished)busy=false;render();
   }).catch(error=>{busy=false;activeWorker.terminate();worker=null;toast(error.message);render();});
  };
  worker.onerror=()=>{busy=false;toast('Simulation interrompue. La dernière sauvegarde cohérente reste disponible.');worker?.terminate();worker=null;render();};
  worker.postMessage({state:payload.state,steps:1200,targetSeason:cursor.targetSeason,targetDay:cursor.targetDay});render();return;
 }
}
if(act==='stop'){if(worker)worker.postMessage({type:'stop'});else stopBeforeStart=true;return}if(act==='watch')continueMatch(s,null,s.mode==='detail'?10:40);if(act==='finish')continueMatch(s,null,10000);if(['watch','finish'].includes(act))settleAdvance(s,true);if(act==='life')lifeAction(s,arg);if(act==='role-request'&&!requestRole(s))toast('Une évaluation est déjà en cours ou le coach attend de nouvelles performances.');if(act==='upgrade'){if(!upgrade(s,arg))toast('Pas assez de points ou plafond atteint.')}if(act==='learn'){if(!learn(s,arg))toast('Prérequis ou points insuffisants.')}if(act==='equip')equip(s,arg);if(act==='sign'){sign(s,Number(arg));leagueSelection=null;selectedTeam=null;}if(act==='decision'){if(decide(s,arg))focusAdvance=true;}if(act==='trade')requestTrade(s);if(act==='relation'){let old=s.activity;s.activity='entourage';s.relationTarget=arg;next(s);s.activity=old;}if(act==='retire'&&confirm('Terminer définitivement cette carrière ?')){retireCareer(s);log(s,'Retraite',`${hero(s).name} quitte les parquets. Votre histoire reste consultable.`)}if(act==='export-legacy'){let url=URL.createObjectURL(new Blob([JSON.stringify(s.legacyArchive)],{type:'application/json'}));let a=document.createElement('a');a.href=url;a.download='hoop-legacy-ancienne-saison.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);return}if(act==='export'){toast('Préparation de l’export complet…');await completeExport(s);let url=URL.createObjectURL(new Blob([JSON.stringify(s)],{type:'application/json'}));let a=document.createElement('a');a.href=url;a.download='hoop-legacy-saison-'+s.season+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);return}if(act==='save'){slotMetadata=await listSlots();const existing=slotMetadata.find(m=>m.key==='slot'+arg);if(existing&&!confirm('Remplacer cette sauvegarde : '+slotLabel(existing)+' ?'))return;await save(s,'slot'+arg);slotMetadata=await listSlots();toast('Emplacement '+arg+' sauvegardé.')}if(act==='delete'){const existing=(await listSlots()).find(m=>m.key==='slot'+arg);if(existing&&confirm('Supprimer cette sauvegarde : '+slotLabel(existing)+' ?')){await deleteSlot('slot'+arg);slotMetadata=await listSlots();}}if(act==='load'){let data=await load(arg==='rollback'?'rollback':arg.startsWith('before-')?arg:'slot'+arg,{lazy:true});if(!data){toast('Cet emplacement est vide.');return}if(confirm('Charger cet emplacement ? La partie actuelle sera gardée en secours.')){await save(s,'before-load');s=data;leagueSelection=null;postSeason=null;selectedTeam=null;creation=false;}}if(act==='install'){await installPrompt?.prompt();installPrompt=null}await persist();render()}
async function readArchiveForView(year){
 if(!year||Number(year)===s.season)return;
 notice='Chargement de la saison…';try{await hydrateArchive(s,year);notice='Saison chargée';}catch(e){toast(e.message);}render();
}
function bind(){
 for(const [id,key] of [['stats-season','season'],['stats-phase','phase'],['stats-club','team'],['stats-sort','sort'],['stats-direction','direction']])if($(id))$(id).onchange=async e=>{statsFilter[key]=e.target.value;statsFilter.page=0;if(key==='season')await readArchiveForView(e.target.value);render();};
 for(const [id,key] of [['awards-season','season'],['awards-kind','kind']])if($(id))$(id).onchange=e=>{awardFilter[key]=e.target.value;render();};
 if($('stats-query'))$('stats-query').oninput=e=>{statsFilter.query=e.target.value;statsFilter.page=0;render();};
 if($('directory-query'))$('directory-query').oninput=e=>{directoryQuery=e.target.value;render();};
 if($('market-preference'))$('market-preference').onchange=async e=>{if(!canChange(s,{busy:busy||acting,pending:true})||!PREFERENCES[e.target.value])return;s.careerPlan.preference=e.target.value;await persist();render();};

 if(s&&!creation){
  const writable=canChange(s,{busy});if(s.retired&&$('mode'))$('mode').disabled=true;
  const ids=['training','activity','training-domain','training-mode','training-intensity','lifestyle','tendency-mode','life-delegate','auto','season-ambition',...['three','drive','post','mid'].map(k=>'tendency-'+k)];
  for(const id of ids)if($(id)&&!writable)$(id).disabled=true;
  document.querySelectorAll('[data-action]').forEach(el=>{if(['upgrade','learn','equip','trade','role-request','retire','life','relation'].includes(el.dataset.action.split(':')[0])&&!writable)el.disabled=true;});
 }
 if($('advance-size'))$('advance-size').onchange=async e=>{if(busy||acting)return;setAdvanceMode(s,e.target.value);await persist();render();};
 for(const [id,change] of [['playoff-season',v=>{postSeason=v;postRound='all';}],['playoff-conference',v=>postConference=v],['playoff-round',v=>postRound=v]])if($(id))$(id).onchange=async e=>{change(e.target.value);if(id==='playoff-season')await readArchiveForView(e.target.value);render();};
for(const domain of ['routine','media','agent','exposure']){const el=$('policy-'+domain);if(el){el.disabled=!canChange(s,{busy});el.onchange=async e=>{if(!canChange(s,{busy:busy||acting}))return;if(setPolicy(s,domain,e.target.value)){await persist();render()}}}}
for(const key of ['percent','reserve','frequency','automatic']){const el=$('finance-'+key);if(el){el.disabled=!canChange(s,{busy});el.onchange=async e=>{if(!canChange(s,{busy:busy||acting}))return;if(setFinance(s,key,key==='automatic'?e.target.checked:e.target.value)){await persist();render()}}}}
if($('season-ambition'))$('season-ambition').onchange=async e=>{if(!canChange(s,{busy:busy||acting}))return;if(chooseAmbition(s,e.target.value)){await persist();render()}};if(busy||acting)document.querySelectorAll('main button,main select,main input').forEach(el=>{if(el.dataset.action!=='stop')el.disabled=true});document.querySelectorAll('[data-action]').forEach(el=>el.onclick=async()=>{if(acting)return;acting=true;document.querySelectorAll('main button,main select,main input').forEach(control=>control.disabled=true);try{await action(el.dataset.action)}catch(e){busy=false;toast(e.message);render()}finally{acting=false;render()}});document.querySelector('.brand')?.addEventListener('click',e=>{e.preventDefault();tab='home';render()});for(let k of KEYS){let el=$('cap-'+k);if(el)el.oninput=()=>{build.caps[k]=Number(el.value);$('v-'+k).textContent=el.value;$('budget').textContent=Math.round(potentialCost(build.caps))}}for(let k of ['training','activity','mode'])if($(k))$(k).onchange=async e=>{if(!canChange(s,{busy,match:k==='mode',pending:k==='mode'}))return;s[k]=e.target.value;await persist()};for(let [id,object,key] of [['training-domain',s?.trainingPlan,'domain'],['training-mode',s?.trainingPlan,'mode'],['training-intensity',s?.trainingPlan,'intensity'],['lifestyle',s?.life,'lifestyle'],['tendency-mode',s?hero(s):null,'tendencyMode']])if($(id))$(id).onchange=async e=>{if(!canChange(s,{busy}))return;object[key]=e.target.value;await persist();render()};if($('life-delegate'))$('life-delegate').onchange=async e=>{if(!canChange(s,{busy}))return;s.life.delegated=e.target.checked;await persist()};for(let k of ['three','drive','post','mid'])if($('tendency-'+k))$('tendency-'+k).onchange=async e=>{if(!canChange(s,{busy}))return;hero(s).tendencies??={};hero(s).tendencies[k]=Math.max(5,Math.min(100,Number(e.target.value)));await persist()};if($('journal-query'))$('journal-query').oninput=e=>{$('journal-results').innerHTML=journalRows(s.journal.filter(v=>(v.title+' '+v.text).toLocaleLowerCase().includes(e.target.value.toLocaleLowerCase())).slice(-60).reverse())};if($('auto'))$('auto').onchange=async e=>{if(!canChange(s,{busy}))return;s.auto=e.target.checked;await persist()};if($('league-select'))$('league-select').onchange=e=>{leagueSelection=e.target.value;selectedTeam=null;archiveSeason=null;render()};if($('calendar-team'))$('calendar-team').onchange=e=>{selectedTeam=e.target.value;render()};if($('calendar-season'))$('calendar-season').onchange=e=>{archiveSeason=e.target.value;render()};if($('team-select'))$('team-select').onchange=e=>{selectedTeam=e.target.value;render()};if($('import'))$('import').onchange=async e=>{try{let file=e.target.files[0];if(!file)return;let raw=await file.text(),data=parseSave(raw);await save(s,'before-import');const original=JSON.parse(raw);if(original.engine!==VERSION)await save(original,'backup-import-'+Date.now());s=data;creation=false;leagueSelection=null;postSeason=null;selectedTeam=null;await persist();toast('Partie importée.');render()}catch(e){toast('Import refusé : '+e.message)}}}
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e});
try{s=await load('auto',{lazy:true});notice=s?'Sauvegarde retrouvée':''}catch(e){try{s=await load('rollback',{lazy:true});if(s){await save(s,'recovery-copy');notice='Copie de secours retrouvée';toast('La dernière copie valide a été retrouvée. Exportez-la depuis le menu ☰.');}else toast('Impossible de lire la sauvegarde : '+e.message);}catch{toast('Sauvegarde illisible. Vous pouvez importer votre export JSON.');}}render();
const hadController=!!navigator.serviceWorker?.controller;
if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js?v=3.5.0').then(r=>{r.update();navigator.serviceWorker.addEventListener('controllerchange',()=>{if(!busy&&hadController)toast('Version 3.5 disponible. Fermez puis rouvrez le jeu pour l’utiliser.');});}).catch(()=>toast('Mode hors ligne indisponible dans ce navigateur.'));
